import 'package:dio/dio.dart'; import 'package:flutter/material.dart'; import 'package:flutter_riverpod/flutter_riverpod.dart'; import 'package:flutter_test/flutter_test.dart'; import 'package:mobile/core/theme/app_theme.dart'; import 'package:mobile/features/chatbot/data/chatbot_api.dart'; import 'package:mobile/features/chatbot/models/chatbot_models.dart'; import 'package:mobile/features/chatbot/providers/chatbot_provider.dart'; import 'package:mobile/features/chatbot/screens/conversations_screen.dart';
void main() { testWidgets('loads, searches with debounce, and shows empty state safely', (tester) async { final api = _Api()..lists.add(Future.value((conversations: const [ConversationSummary(id: 'c1', title: 'Headache', messageCount: 2)], pagination: null)))..searches.add(Future.value(const [ConversationSummary(id: 'c1', title: 'Headache')])); await tester.pumpWidget(_app(api)); await tester.pump(); expect(find.text('Headache'), findsOneWidget); await tester.enterText(find.byType(TextFormField), 'he'); await tester.pump(const Duration(milliseconds: 400)); await tester.pump(); expect(api.searchQueries, ['he']); }); }
Widget _app(_Api api) => ProviderScope(overrides: [chatbotApiProvider.overrideWithValue(api)], child: MaterialApp(theme: AppTheme.light(), home: const ConversationsScreen()));
class _Api extends ChatbotApi { _Api() : super(Dio()); final lists = <Future<({List<ConversationSummary> conversations, ChatPagination? pagination})>>[]; final searches = <Future<List<ConversationSummary>>>[]; final searchQueries = <String>[]; @override Future<({List<ConversationSummary> conversations, ChatPagination? pagination})> listConversations({int page = 1, int limit = 50, String? search}) => lists.removeAt(0); @override Future<List<ConversationSummary>> searchConversations(String query) { searchQueries.add(query); return searches.removeAt(0); } }
